function promptPublish(r){const safety=r.key==='platform_safety';openModal(safety?'审核平台安全底线':'确认发布场景提示词',`<p class="modal-note">仅发布服务器已保存草稿，不包括未保存的编辑。${safety?'平台安全底线是所有场景的首层约束，不得被场景提示词覆盖。':''}发布将创建新版本，只作用于新会话和新课堂；进行中的会话继续使用冻结版本。原师生端未接入。</p><form id="prompt-publish-form"><div class="error" role="alert"></div>${safety?'<label class="safety-check"><input name="confirm" type="checkbox" required>我已审核安全底线与未成年人保护要求，确认场景不能覆盖该层约束。</label>':''}<div class="form-actions"><button type="button" data-action="close-modal">取消</button><button type="submit" class="primary">确认发布已保存草稿</button></div></form>`);$('#prompt-publish-form').onsubmit=async ev=>{ev.preventDefault();await submitForm(ev.currentTarget,async()=>{const out=await api('/prompts/'+r.key+'/publish',{method:'POST',body:safety?{confirm_safety:true}:{}});const check=await api('/prompts/'+r.key);if(check.current_version!==out.current_version)throw Error('发布后版本核验失败。');$('#modal').close();await render();notice('提示词已发布为新版本。');});};}

$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close();}});
